(function(){'use strict';const api=window.AvalonOverlay,$=id=>document.getElementById(id);function paint({zone:z}){if(!z)return;$('zone-name').textContent=z.name;$('zone-meta').textContent='T'+z.tier+' · '+AvalonMath.worlds[z.world];const img=new Image();img.alt='Карта '+z.name;img.src='avalon-local/'+encodeURIComponent(z.image);$('map').replaceChildren(img);$('features').textContent=z.resources.map(r=>AvalonMath.resources[r.type]+' T'+r.max_tier).join(' · ')+'\n'+z.chests.map(c=>(AvalonMath.chests[c.type]||c.type)+' ×'+c.count).join(' · ');}api.onZone(paint);api.state().then(paint);$('close').onclick=()=>api.control('close');$('pin').onclick=async()=>{const state=await api.control('pin');$('pin').setAttribute('aria-pressed',String(state.pinned));};})();
